create or replace function public.get_my_learner_passport_v2() returns jsonb language plpgsql stable security invoker set search_path='' as $$
declare v_uid uuid:=(select auth.uid());v_p public.profiles%rowtype;v_stage public.education_audience_stages%rowtype;v_mastery jsonb;v_old jsonb;v_name text;v_progress numeric;begin
 if v_uid is null then raise exception 'authentication required';end if;select * into v_p from public.profiles where id=v_uid;if not found then raise exception 'profile not found';end if;select * into v_stage from public.education_audience_stages where stage_key=v_p.education_stage_key;v_mastery:=public.get_my_mastery_engine();begin v_old:=public.get_my_career_passport_summary();exception when others then v_old:='{}'::jsonb;end;
 v_name:=case v_p.education_stage_key when 'school_1_6' then 'Growth Passport' when 'school_7_8' then 'Exploration Passport' when 'school_9_10' then 'Skills Passport' when 'school_11_12' then 'Transition Passport' else 'Career Passport' end;
 v_progress:=least(100,round((coalesce((v_mastery->>'overall_score')::numeric,0)*0.45)+(coalesce((v_old->>'profile_score')::numeric,0)*0.25)+(least(100,(select count(*)*12 from public.learner_projects where user_id=v_uid and status in ('submitted','verified')))*0.15)+(least(100,(select count(*)*10 from public.verified_skills where user_id=v_uid))*0.15),2));
 return jsonb_build_object('passport_name',v_name,'stage_key',v_p.education_stage_key,'stage_title',v_stage.title,'grade_level',v_p.grade_level,'institution_name',v_p.institution_name,'progression_score',v_progress,'mastery',v_mastery,'profile_summary',v_old,'verified_skills',coalesce((select jsonb_agg(to_jsonb(vs) order by vs.issued_at desc) from public.verified_skills vs where vs.user_id=v_uid),'[]'::jsonb),'projects',coalesce((select jsonb_agg(to_jsonb(p) order by p.created_at desc) from (select * from public.learner_projects where user_id=v_uid order by created_at desc limit 12)p),'[]'::jsonb),'achievements',coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at desc) from (select * from public.career_passport_achievements where user_id=v_uid order by created_at desc limit 12)a),'[]'::jsonb),'evidence_summary',jsonb_build_object('mastery_evidence',(select count(*) from public.learner_mastery_evidence where user_id=v_uid),'verified_mastery_evidence',(select count(*) from public.learner_mastery_evidence where user_id=v_uid and verified),'projects',(select count(*) from public.learner_projects where user_id=v_uid),'verified_projects',(select count(*) from public.learner_projects where user_id=v_uid and verified)));
end;$$;
;
